const g=new THREE.Group();
const rnd=ctx.rngFrom(11);
const mat=ctx.makeMat({color:'#ff7ad9',emissive:'#551144',rough:0.5});
for(let k=0;k<6;k++){
  const pts=[]; const p=new THREE.Vector3(rnd()-.5,rnd()-.5,rnd()-.5).multiplyScalar(1.2);
  for(let i=0;i<14;i++){
    p.add(new THREE.Vector3(rnd()-.5,rnd()-.5,rnd()-.5).multiplyScalar(0.7));
    if(p.length()>0.9) p.multiplyScalar(0.9/p.length());
    pts.push(p.clone());
  }
  g.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts),80,0.035,6,false),mat));
}
return g;
